function googleProfileForm(){return '<div class="auth-wrap">'+brand()+'<form class="auth-card" id="google-profile-form"><p class="eyebrow">GOOGLE SIGN-IN · 18+</p><h1>Finish your <span>TM profile</span></h1><p class="lead">Your Google account is verified. Complete these details to create your TM account.</p>'+errorHtml()+'<div class="form-grid"><label>Display name<input name="display_name" required maxlength="70" value="'+safe(googleProfile?.display_name||"")+'"></label><label>Date of birth<input name="birth_date" type="date" required max="'+new Date(Date.now()-18*365.25*86400000).toISOString().slice(0,10)+'"></label><label>Gender<select name="gender" required><option value="">Select</option><option>Woman</option><option>Man</option><option>Non-binary</option><option>Other</option><option>Prefer not to say</option></select></label><label>Country<select name="country" id="signup-country" required>'+countryOptions("Nigeria")+'</select></label><label>City<select name="city" id="signup-city" required>'+cityOptions("Nigeria")+'</select></label><label>Looking for<select name="looking_for" required><option value="">Select</option><option value="friends">Friends</option><option value="dating">Dating</option><option value="both">Both</option></select></label><label class="wide">Languages<input name="languages" placeholder="English, Yoruba"></label><label class="wide">Bio<textarea name="bio" rows="3" maxlength="300"></textarea></label></div><label class="terms"><input type="checkbox" name="terms" required> I agree to the Terms and Privacy Policy.</label><button class="primary-button full" type="submit" '+(busy?"disabled":"")+'>'+(busy?"Creating account…":"Create TM account")+'</button><p class="auth-small">TM is for adults aged 18+.</p></form></div>';}
