function credentialScreen(){return '<div class="auth-wrap">'+brand()+'<div class="auth-card"><p class="eyebrow">SAVE THIS NOW</p><h1>Your TM account is ready</h1><p class="lead">This code is shown only once. Save it somewhere private.</p><div class="credential-box"><label>TM number</label><strong>'+safe(showCode?.user.tm_number)+'</strong><label>4-digit code</label><strong class="pin-display">'+safe(showCode?.pin)+'</strong></div><button class="primary-button full" data-copy="'+safe(showCode?.user.tm_number+"  PIN: "+showCode?.pin)+'">Copy credentials</button><button class="secondary-button full" data-auth="continue">I saved my code — continue</button><p class="auth-small">Never share your PIN. TM number is an app ID, not a phone number.</p></div></div>';}
async function loadDiscover(){
if(!session){discoverProfiles=[];discoverLoading=false;render();return;}
discoverLoading=true;render();
try{const [profiles,matches]=await Promise.all([api("discover_list",{session_token:session}),api("match_list",{session_token:session})]);discoverProfiles=profiles.profiles||[];discoverTotalProfiles=Number(profiles.total_profiles||0);
// Never fabricate demo dating profiles: show only real, completed member profiles.
discoverMatches=matches.matches||[];discoverNotifications=matches.notifications||[];}
catch(err){console.warn("Discover could not load",err);discoverNotice="We couldn’t refresh profiles. Please try again.";}
finally{discoverLoading=false;render();}
}
async function decideDiscover(target,decision){if(!target||discoverDecisionBusy)return;const old=discoverProfiles.find(x=>x.id===target);if(!old)return;discoverDecisionBusy=true;discoverProfiles=discoverProfiles.filter(x=>x.id!==target);render();try{const result=await api(decision==="like"?"discover_like":"discover_pass",{session_token:session,target_user_id:target});if(result.matched)discoverNotice="It’s a match with "+(old?.display_name||"someone special")+"!";}catch(err){discoverProfiles.unshift(old);discoverNotice=err.message||"Could not save your swipe. Please try again.";render();discoverDecisionBusy=false;return;}discoverDecisionBusy=false;if(discoverProfiles.length){render();}else{await loadDiscover();}if(discoverNotice)render();}
async function prefetchChatMessages(chats){await Promise.all(chats.map(async chat=>{try{const out=await api("chat_messages",{session_token:session,chat_id:chat.id});localStorage.setItem("tm_chat_cache_"+chat.id,JSON.stringify(out.messages||[]));}catch(e){console.warn("Chat prefetch skipped",e);}}));}
async function loadChatList(){chatListLoading=true;try{const cached=JSON.parse(localStorage.getItem("tm_chat_list_cache")||"[]");if(Array.isArray(cached)&&cached.length){chatList=cached;render();}const out=await api("chat_list",{session_token:session});chatList=out.chats||[];localStorage.setItem("tm_chat_list_cache",JSON.stringify(chatList));chatListLoading=false;render();prefetchChatMessages(chatList);}catch(err){chatListLoading=false;formError=err.message;render();}}
async function loadChatMessages(){if(!activeChat)return;const chatId=activeChat.id;chatLoading=true;try{const out=await api("chat_messages",{session_token:session,chat_id:chatId});if(!activeChat||activeChat.id!==chatId)return;chatMessages=out.messages||[];try{localStorage.setItem("tm_chat_cache_"+chatId,JSON.stringify(chatMessages));}catch{}chatLoading=false;render();const box=app.querySelector(".chat-messages");if(box)box.scrollTop=box.scrollHeight;}catch(err){chatLoading=false;if(!chatMessages.length)render();console.warn("Could not refresh chat messages",err);}}
function tmUpdateChatViewport(){if(!document.body.classList.contains("tm-chat-open"))return;const vv=window.visualViewport;if(vv){document.documentElement.style.setProperty("--tm-vv-height",vv.height+"px");document.documentElement.style.setProperty("--tm-vv-top",vv.offsetTop+"px");}else{document.documentElement.style.setProperty("--tm-vv-height",window.innerHeight+"px");document.documentElement.style.setProperty("--tm-vv-top","0px");}}
if(window.visualViewport){window.visualViewport.addEventListener("resize",tmUpdateChatViewport);window.visualViewport.addEventListener("scroll",tmUpdateChatViewport);}window.addEventListener("resize",tmUpdateChatViewport);document.addEventListener("focusin",e=>{if(e.target.closest(".chat-compose"))requestAnimationFrame(tmUpdateChatViewport);});document.addEventListener("focusout",()=>setTimeout(tmUpdateChatViewport,120));
function render(){document.body.classList.toggle("tm-chat-open",Boolean(activePage==="chats"&&activeChat));if(showCode){app.innerHTML=credentialScreen();wire();return;}if(!session&&!guest){app.innerHTML=authView==="google_profile"?googleProfileForm():welcome();wire();return;}app.innerHTML=shell();wire();if(session&&!freeFireData.loaded&&!freeFireData.loading)loadFreeFire();if(activePage==="chats"&&activeChat)requestAnimationFrame(()=>{const box=app.querySelector(".chat-messages");if(box)box.scrollTop=box.scrollHeight;});}
